parameters.cypher_query:
MATCH (b:Battle)<-[:ATTACKER_COMMANDER|DEFENDER_COMMANDER]-(p:Person)
RETURN gds.graph.project(
  'battles_graph', b, p,
  {
    sourceNodeLabels: labels(b),
    targetNodeLabels: labels(p)
  },
  { undirectedRelationshipTypes: ['ATTACKER_COMMANDER', 'DEFENDER_COMMANDER'] }
)

MATCH (b:Battle)<-[:ATTACKER_COMMANDER|DEFENDER_COMMANDER]-(p:Person)
RETURN gds.graph.project(
  'battles_graph', b, p,
  {
    sourceNodeLabels: labels(b),
    targetNodeLabels: labels(p)
  },
  { undirectedRelationshipTypes: ['ATTACKER_COMMANDER', 'DEFENDER_COMMANDER'] }
)

MATCH (b:Battle)<-[:ATTACKER|DEFENDER]-(h:House)
RETURN gds.graph.project(
  'battles_graph', b, h,
  {
    sourceNodeLabels: labels(b),
    targetNodeLabels: labels(h)
  },
  { undirectedRelationshipTypes: ['ATTACKER', 'DEFENDER'] }
)

MATCH (b:Battle)<-[:ATTACKER_COMMANDER]-(p:Person) RETURN gds.graph.project( 'battles_graph', b, p, {
  sourceNodeLabels: ['Battle'],
  targetNodeLabels: ['Person'],
  relationshipType: 'ATTACKER_COMMANDER'
},
{ undirectedRelationshipTypes: ['ATTACKER_COMMANDER'] })

